export function getCadeiaTransporteEletronsChallenges(): ChallengeSet {
  return {
    title: "Desafio: Cadeia de Transporte de Elétrons",
    description: "Fosforilação oxidativa, inibidores, desacopladores e produção de ATP mitocondrial.",
    challenges: [
      { type: "mcq", question: "Quantos ATP são produzidos por cada NADH na fosforilação oxidativa?", options: ["1.5", "2.5", "3.0", "4.0"], correctIndex: 1, explanation: "Cada NADH gera ~2.5 ATP (10 H⁺ bombeados, ~4 H⁺ por ATP). FADH2 entra no Complexo II e gera ~1.5 ATP.", reference: "Lehninger, Cap. 19" },
      { type: "adjust", question: "Simule intoxicação por cianeto: ative o cianeto e observe a parada da cadeia.", targetParams: { atpRate: { min: 0, max: 5, label: "ATP/s" } }, validator: (s) => { const cyanideActive = s.cyanide === true; const atp = s.atpRate ?? 10; return (cyanideActive && atp <= 5) ? { correct: true, feedback: "Cadeia bloqueada pelo cianeto — ATP quase zero!" } : { correct: false, feedback: cyanideActive ? `ATP: ${atp}. Aguarde a simulação estabilizar.` : "Ative o cianeto no simulador." }; }, explanation: "O cianeto bloqueia o Complexo IV (citocromo c oxidase), impedindo a transferência de e⁻ ao O₂. Toda a cadeia para.", reference: "Lehninger, Cap. 19" },
      { type: "mcq", question: "A rotenona inibe qual complexo?", options: ["Complexo I", "Complexo II", "Complexo III", "Complexo IV"], correctIndex: 0, explanation: "A rotenona bloqueia a transferência de e⁻ do NADH para a ubiquinona no Complexo I. É um pesticida e ferramenta experimental.", reference: "Lehninger, Cap. 19" },
      { type: "mcq", question: "O DNP (dinitrofenol) causa perda de peso porque:", options: ["Bloqueia a cadeia", "Desacopla: dissipa gradiente H⁺ como calor sem gerar ATP", "Inibe a glicólise", "Aumenta o Vmax"], correctIndex: 1, explanation: "Desacopladores transportam H⁺ pela membrana, dissipando o gradiente. A cadeia continua (↑O₂) mas sem ATP → energia liberada como calor → hipertermia letal.", reference: "Lehninger, Cap. 19" },
      { type: "mcq", question: "A antimicina A bloqueia:", options: ["Complexo I → II", "Complexo II → III", "Complexo III (citocromo bc1)", "ATP sintase"], correctIndex: 2, explanation: "A antimicina A bloqueia a transferência de e⁻ no Complexo III, no ciclo Q. Impede o fluxo de ubiquinol para citocromo c.", reference: "Lehninger, Cap. 19" },
      { type: "adjust", question: "Maximize a produção de ATP: NADH e FADH2 altos, sem inibidores.", targetParams: { nadh: { min: 80, max: 100, label: "NADH" }, fadh2: { min: 60, max: 100, label: "FADH₂" } }, validator: (s) => { const atp = s.atpRate ?? 0; const noInhibitors = !s.rotenone && !s.antimycinA && !s.cyanide && !s.dnp; return (atp >= 25 && noInhibitors) ? { correct: true, feedback: "Produção máxima de ATP alcançada!" } : { correct: false, feedback: `ATP: ${atp}. Desative inibidores e aumente substratos.` }; }, explanation: "Em condições ótimas, a fosforilação oxidativa de 1 glicose gera ~30-32 ATP (10 NADH + 2 FADH2 + 2 ATP da glicólise + 2 GTP do ciclo de Krebs).", reference: "Lehninger, Cap. 19" },
      { type: "mcq", question: "A oligomicina inibe:", options: ["Complexo I", "Complexo III", "ATP sintase (Complexo V)", "Translocase de adenina"], correctIndex: 2, explanation: "A oligomicina bloqueia o canal de H⁺ da ATP sintase (subunidade F₀), impedindo a síntese de ATP. O gradiente acumula e a cadeia desacelera.", reference: "Lehninger, Cap. 19" },
      { type: "mcq", question: "O aceitador final de eletrões na cadeia é:", options: ["NAD⁺", "FAD", "O₂ (oxigênio molecular)", "Citocromo c"], correctIndex: 2, explanation: "O O₂ recebe 4 e⁻ e 4 H⁺ no Complexo IV, formando 2 H₂O. Sem O₂, toda a cadeia bloqueia (anaerobiose).", reference: "Lehninger, Cap. 19" },
      { type: "mcq", question: "A termoGenina (UCP1) no tecido adiposo marrom:", options: ["É um inibidor da cadeia", "É um desacoplador endógeno que gera calor (termogênese)", "Aumenta a produção de ATP", "Inibe a β-oxidação"], correctIndex: 1, explanation: "UCP1 permite a reentrada de H⁺ na matriz sem passar pela ATP sintase, dissipando o gradiente como calor. Essencial na termogênese neonatal.", reference: "Lehninger, Cap. 19" },
      { type: "mcq", question: "O rendimento de ATP do FADH₂ é menor que o do NADH porque:", options: ["FADH₂ não é oxidado", "FADH₂ entra no Complexo II, bombeando menos H⁺", "FADH₂ é mais instável", "FADH₂ não gera gradiente"], correctIndex: 1, explanation: "FADH₂ entra no Complexo II (succinato desidrogenase), que NÃO bombeia H⁺. O NADH entra no Complexo I, que bombeia 4 H⁺. Diferença: ~1 ATP.", reference: "Lehninger, Cap. 19" },
    ],
  };
}

export function getDissociacaoHemoglobinaChallenges(): ChallengeSet {
  return {
    title: "Desafio: Dissociação da Hemoglobina",
    description: "Curva de saturação, efeito Bohr, fatores que desviam a curva e aplicações clínicas.",
    challenges: [
      { type: "mcq", question: "O efeito Bohr descreve:", options: ["Ligação de CO à hemoglobina", "Redução da afinidade Hb-O₂ por ↓pH ou ↑CO₂", "Aumento da afinidade por ↑temperatura", "Deslocamento para a esquerda por 2,3-BPG"], correctIndex: 1, explanation: "O efeito Bohr: pH↓ e CO₂↑ estabilizam a forma T (desoxigenada) da Hb, facilitando a liberação de O₂ nos tecidos ativos.", reference: "Lehninger, Cap. 5" },
      { type: "adjust", question: "Simule exercício intenso: desvie a curva para a direita (P50 > 30 mmHg).", targetParams: { pH: { min: 7.1, max: 7.3, label: "pH" }, temp: { min: 38, max: 40, label: "Temperatura" } }, validator: (s) => { const p50 = s.p50 ?? 26.7; return p50 > 30 ? { correct: true, feedback: "Curva desviada para a direita — mais O₂ liberado nos tecidos!" } : { correct: false, feedback: `P50: ${p50} mmHg. Reduza pH e aumente temperatura.` }; }, explanation: "No exercício: pH↓, CO₂↑, temp↑, 2,3-BPG↑ → desvio direito → P50↑ → maior descarga de O₂ nos músculos.", reference: "Guyton & Hall, Cap. 40" },
      { type: "mcq", question: "O monóxido de carbono (CO) é perigoso porque:", options: ["Reduz a produção de eritrócitos", "Liga-se à Hb com afinidade 200x > O₂ e desvia a curva para a esquerda", "Causa acidose metabólica diretamente", "Destrói a membrana eritrocitária"], correctIndex: 1, explanation: "CO forma carboxihemoglobina (HbCO), que não transporta O₂. Além disso, desvia a curva para a esquerda nas subunidades restantes, agravando a hipóxia.", reference: "Harrison's, Cap. 472" },
      { type: "mcq", question: "A hemoglobina fetal (HbF) tem maior afinidade por O₂ porque:", options: ["Tem mais subunidades", "As cadeias γ ligam menos 2,3-BPG que as cadeias β", "É menor que a HbA", "Não sofre efeito Bohr"], correctIndex: 1, explanation: "HbF (α2γ2) liga 2,3-BPG com menor afinidade que HbA (α2β2), mantendo a curva à esquerda → facilita captação de O₂ da placenta.", reference: "Lehninger, Cap. 5" },
      { type: "adjust", question: "Simule intoxicação por CO: ajuste pH alto (7.5) e pCO₂ baixo para P50 < 22 mmHg.", targetParams: { pH: { min: 7.45, max: 7.55, label: "pH" }, pCO2: { min: 25, max: 32, label: "pCO₂" } }, validator: (s) => { const p50 = s.p50 ?? 26.7; return p50 < 22 ? { correct: true, feedback: "Curva desviada para a esquerda — O₂ retido na Hb!" } : { correct: false, feedback: `P50: ${p50} mmHg. Alcalinize mais.` }; }, explanation: "Desvio esquerdo = ↑afinidade Hb-O₂ = menor liberação tecidual. No CO, mesmo com saturação 'normal' no pulso-oxímetro, os tecidos estão hipóxicos.", reference: "Harrison's, Cap. 472" },
      { type: "mcq", question: "O 2,3-bisfosfoglicerato (2,3-BPG) é produzido:", options: ["No fígado", "Nos eritrócitos, a partir de 1,3-BPG da glicólise", "Nos pulmões", "Na medula óssea"], correctIndex: 1, explanation: "O 2,3-BPG é formado pela mutase no desvio de Rapoport-Luebering da glicólise eritrocitária. Liga-se ao centro da desoxi-Hb (forma T).", reference: "Lehninger, Cap. 5" },
      { type: "mcq", question: "Na anemia, o 2,3-BPG:", options: ["Diminui", "Aumenta (compensação)", "Não se altera", "É substituído por ATP"], correctIndex: 1, explanation: "Na anemia crônica, ↑2,3-BPG é uma compensação que desloca a curva para a direita, facilitando a liberação de O₂ para os tecidos.", reference: "Guyton & Hall, Cap. 40" },
      { type: "mcq", question: "A cooperatividade positiva da Hb resulta em curva:", options: ["Hiperbólica", "Sigmoide", "Linear", "Exponencial"], correctIndex: 1, explanation: "A ligação de O₂ a uma subunidade facilita a ligação nas demais (transição T→R). Isso gera a curva sigmoide e o coeficiente de Hill ~2.8.", reference: "Lehninger, Cap. 5" },
      { type: "mcq", question: "A mioglobina tem curva hiperbólica porque:", options: ["Tem 4 subunidades", "É monomérica — sem cooperatividade", "Liga apenas CO", "Não liga O₂"], correctIndex: 1, explanation: "A mioglobina (1 subunidade) segue Michaelis-Menten: curva hiperbólica, alta afinidade (P50 ~2.8 mmHg), armazena O₂ no músculo.", reference: "Lehninger, Cap. 5" },
      { type: "mcq", question: "O sangue armazenado em banco perde eficácia porque:", options: ["O 2,3-BPG diminui, desviando a curva para a esquerda", "A Hb se desnatura", "O O₂ escapa", "As plaquetas agregam"], correctIndex: 0, explanation: "No sangue armazenado, o 2,3-BPG cai (glicólise para), desviando a curva para esquerda → Hb retém O₂ e liberta menos. Melhora 24h após transfusão.", reference: "Harrison's, Cap. 109" },
    ],
  };
}

export function getGlicoliseGliconeogeneseChallenges(): ChallengeSet {
  return {
    title: "Desafio: Glicólise vs Gliconeogénese",
    description: "Regulação metabólica, enzimas-chave, estados alimentado/jejum e patologias.",
    challenges: [
      { type: "mcq", question: "A enzima reguladora principal da glicólise é:", options: ["Hexoquinase", "Fosfofrutoquinase-1 (PFK-1)", "Piruvato quinase", "Aldolase"], correctIndex: 1, explanation: "A PFK-1 é o passo limitante e mais regulado da glicólise. Ativada por AMP, F2,6BP; inibida por ATP, citrato.", reference: "Lehninger, Cap. 15" },
      { type: "mcq", question: "No estado alimentado, a razão insulina/glucagon está:", options: ["Baixa", "Alta", "Igual a 1", "Variável"], correctIndex: 1, explanation: "Insulina alta promove: ↑glicólise, ↑glicogênese, ↑lipogênese. Glucagon baixo → ↓gliconeogênese, ↓glicogenólise.", reference: "Lehninger, Cap. 15" },
      { type: "adjust", question: "Simule jejum prolongado: glucagon >80% e insulina <20%.", targetParams: { glucagon: { min: 80, max: 100, label: "Glucagon" }, insulin: { min: 0, max: 20, label: "Insulina" } }, validator: (s) => { const g = s.glucagon ?? 50; const i = s.insulin ?? s.insulina ?? 50; return (g >= 80 && i <= 20) ? { correct: true, feedback: "Jejum simulado — gliconeogênese ativada!" } : { correct: false, feedback: `Glucagon: ${g}%, Insulina: ${i}%. Ajuste.` }; }, explanation: "No jejum, glucagon↑ ativa PKA → fosforila PFK-2/FBPase-2 → ↓F2,6BP → ↓glicólise e ↑gliconeogênese hepática.", reference: "Lehninger, Cap. 15" },
      { type: "mcq", question: "A frutose-2,6-bisfosfato (F2,6BP) é o ativador alostérico mais potente de:", options: ["G6Pase", "PEPCK", "PFK-1", "Piruvato carboxilase"], correctIndex: 2, explanation: "F2,6BP ativa a PFK-1 e inibe a FBPase-1. É produzida pela PFK-2, regulada pela insulina (desfosforilação → ↑PFK-2).", reference: "Lehninger, Cap. 15" },
      { type: "mcq", question: "Qual substrato NÃO pode ser usado na gliconeogênese?", options: ["Lactato", "Alanina", "Glicerol", "Ácidos gordos (acetil-CoA)"], correctIndex: 3, explanation: "Acetil-CoA dos ácidos gordos não pode ser convertido em glicose em mamíferos (reação piruvato desidrogenase é irreversível). Exceção: ácidos gordos de cadeia ímpar → propionil-CoA.", reference: "Lehninger, Cap. 16" },
      { type: "mcq", question: "A metformina reduz a gliconeogênese hepática via:", options: ["Inibição de CYP3A4", "Ativação de AMPK", "Bloqueio de GLUT2", "Estimulação de insulina"], correctIndex: 1, explanation: "AMPK ativada pela metformina: ↓expressão de PEPCK e G6Pase, ↑captação de glicose muscular, ↓síntese lipídica hepática.", reference: "Rang & Dale, Cap. 30" },
      { type: "mcq", question: "O ciclo de Cori envolve:", options: ["Glicose → lactato (músculo) → lactato → glicose (fígado)", "Glicose → piruvato → CO₂", "Conversão de aminoácidos em glicose", "β-oxidação → ATP"], correctIndex: 0, explanation: "No ciclo de Cori, o lactato produzido anaerobicamente no músculo é transportado ao fígado e convertido em glicose (gliconeogênese). Custo: 6 ATP.", reference: "Lehninger, Cap. 16" },
      { type: "mcq", question: "A G6Pase é exclusiva do fígado (e rim) porque:", options: ["Outros tecidos não fazem glicólise", "Apenas o fígado pode liberar glicose para o sangue", "É inibida no músculo", "Não tem relevância metabólica"], correctIndex: 1, explanation: "A G6Pase converte G6P em glicose livre. O músculo não tem G6Pase → G6P fica 'presa' e é usada localmente. Apenas o fígado pode exportar glicose.", reference: "Lehninger, Cap. 16" },
      { type: "mcq", question: "No exercício anaeróbico intenso, o piruvato é convertido em:", options: ["Acetil-CoA", "Oxaloacetato", "Lactato (pela lactato desidrogenase)", "Etanol"], correctIndex: 2, explanation: "Sem O₂ suficiente, a LDH regenera NAD⁺ convertendo piruvato em lactato. Isso permite que a glicólise continue. O lactato causa fadiga e acidose.", reference: "Lehninger, Cap. 14" },
      { type: "mcq", question: "A regulação recíproca garante que glicólise e gliconeogênese:", options: ["Funcionem simultaneamente", "Nunca funcionem ao mesmo tempo (ciclo fútil)", "Só operem no fígado", "Sejam idênticas"], correctIndex: 1, explanation: "A regulação recíproca (via F2,6BP, fosforilação de enzimas) impede ciclos fúteis. Quando uma via está ativa, a oposta é inibida.", reference: "Lehninger, Cap. 15" },
    ],
  };
}

export function getCineticaAvancadaChallenges(): ChallengeSet {
  return {
    title: "Desafio: Cinética Enzimática Avançada",
    description: "Inibição competitiva, não-competitiva e acompetitiva com análise de Lineweaver-Burk.",
    challenges: [
      { type: "mcq", question: "Na inibição acompetitiva, o inibidor liga-se ao:", options: ["Sítio ativo livre", "Complexo enzima-substrato (ES)", "Sítio alostérico da enzima livre", "Produto da reação"], correctIndex: 1, explanation: "O inibidor acompetitivo liga-se APENAS ao complexo ES, reduzindo tanto Km quanto Vmax proporcionalmente.", reference: "Lehninger, Cap. 6" },
      { type: "mcq", question: "No gráfico de Lineweaver-Burk, a inibição acompetitiva mostra:", options: ["Linhas convergindo no eixo X", "Linhas convergindo no eixo Y", "Linhas paralelas", "Mesma linha"], correctIndex: 2, explanation: "Linhas paralelas: mesmo Km/Vmax ratio (mesma inclinação). Intercepto Y e X mudam, mas a inclinação (Km/Vmax) é constante.", reference: "Lehninger, Cap. 6" },
      { type: "adjust", question: "Selecione inibição competitiva e aumente o inibidor: observe Km↑ com Vmax constante.", targetParams: { inhibitorConc: { min: 50, max: 100, label: "Concentração do Inibidor" } }, validator: (s) => { const conc = s.inhibitorConc ?? s.inhibitorConcentration ?? 0; return conc >= 50 ? { correct: true, feedback: "Inibidor competitivo aplicado!" } : { correct: false, feedback: `Concentração: ${conc}%. Aumente para ≥50%.` }; }, explanation: "Na inibição competitiva, Km aparente = Km × (1 + [I]/Ki). O Vmax permanece inalterado pois pode ser alcançado com [S] suficiente.", reference: "Lehninger, Cap. 6" },
      { type: "mcq", question: "O lítio, usado no transtorno bipolar, inibe a GSK-3β de forma:", options: ["Competitiva", "Não-competitiva", "Acompetitiva", "Irreversível"], correctIndex: 2, explanation: "O lítio é um inibidor acompetitivo da GSK-3β: liga-se ao complexo enzima-substrato, reduzindo Km e Vmax proporcionalmente.", reference: "Goodman & Gilman, Cap. 16" },
      { type: "mcq", question: "A eficiência catalítica de uma enzima é dada por:", options: ["Km/Vmax", "kcat/Km", "Vmax × Km", "1/Km"], correctIndex: 1, explanation: "kcat/Km é a medida de eficiência catalítica ou 'especificidade'. Enzimas 'cataliticamente perfeitas' atingem ~10⁸-10⁹ M⁻¹s⁻¹ (limitado pela difusão).", reference: "Lehninger, Cap. 6" },
      { type: "adjust", question: "Aplique inibição não-competitiva: observe Vmax↓ com Km inalterado.", targetParams: { inhibitorConc: { min: 50, max: 100, label: "Concentração do Inibidor" } }, validator: (s) => { const conc = s.inhibitorConc ?? s.inhibitorConcentration ?? 0; return conc >= 50 ? { correct: true, feedback: "Inibição não-competitiva aplicada!" } : { correct: false, feedback: `Concentração: ${conc}%. Aumente para ≥50%.` }; }, explanation: "O inibidor não-competitivo reduz a concentração de enzima funcional (Vmax↓) sem afetar a afinidade pelo substrato (Km inalterado).", reference: "Lehninger, Cap. 6" },
      { type: "mcq", question: "Enzimas alostéricas diferem de enzimas michaelianas porque:", options: ["Não têm sítio ativo", "Apresentam cinética sigmoide e cooperatividade", "Funcionam apenas in vitro", "Não são reguladas"], correctIndex: 1, explanation: "Enzimas alostéricas: múltiplas subunidades, cooperatividade (coeficiente de Hill > 1), curva sigmoide. Reguladas por efetores alostéricos.", reference: "Lehninger, Cap. 6" },
      { type: "mcq", question: "Um Km baixo indica:", options: ["Baixa afinidade", "Alta afinidade da enzima pelo substrato", "Enzima inativa", "Concentração alta de substrato necessária"], correctIndex: 1, explanation: "Km = [S] onde V = Vmax/2. Km baixo → a enzima atinge metade da Vmax com pouco substrato → alta afinidade.", reference: "Lehninger, Cap. 6" },
      { type: "mcq", question: "A inibição por excesso de substrato ocorre em:", options: ["Todas as enzimas", "Enzimas com múltiplos sítios de ligação de substrato", "Apenas enzimas alostéricas", "Nunca ocorre"], correctIndex: 1, explanation: "Em altas [S], um segundo substrato pode ligar-se ao sítio ativo de forma improdutiva, inibindo a enzima (ex: urease em altas [ureia]).", reference: "Lehninger, Cap. 6" },
      { type: "mcq", question: "No Lineweaver-Burk (1/V vs 1/[S]), o intercepto Y representa:", options: ["1/Km", "-1/Km", "1/Vmax", "Vmax"], correctIndex: 2, explanation: "Intercepto Y (quando 1/[S]=0): 1/Vmax. Intercepto X (quando 1/V=0): -1/Km. Inclinação: Km/Vmax.", reference: "Lehninger, Cap. 6" },
    ],
  };
}

export function getCicloUreiaChallenges(): ChallengeSet {
  return {
    title: "Desafio: Ciclo da Ureia",
    description: "Enzimas do ciclo, defeitos congénitos, hiperamonemia e diagnóstico diferencial.",
    challenges: [
      { type: "mcq", question: "Qual é o primeiro passo do ciclo da ureia e onde ocorre?", options: ["OTC no citoplasma", "CPS I na mitocôndria", "ASS no citoplasma", "Arginase no citoplasma"], correctIndex: 1, explanation: "CPS I catalisa: NH₃ + CO₂ + 2 ATP → carbamil-fosfato na matriz mitocondrial. Ativada alostericamente pelo N-acetilglutamato.", reference: "Lehninger, Cap. 18" },
      { type: "mcq", question: "A deficiência de OTC é diferenciada da de CPS I pela presença de:", options: ["Hiperamonemia", "Ácido orótico elevado na urina", "Citrulina plasmática baixa", "Convulsões"], correctIndex: 1, explanation: "Na deficiência de OTC, o carbamil-fosfato acumulado é desviado para a via das pirimidinas → ácido orótico↑. Na CPS I, não há carbamil-fosfato, logo ácido orótico normal.", reference: "Lehninger, Cap. 18" },
      { type: "mcq", question: "O benzoato de sódio trata a hiperamonemia porque:", options: ["Ativa o ciclo da ureia", "Conjuga com glicina formando hipurato (via alternativa de excreção de N)", "Bloqueia a absorção intestinal de NH₃", "Estimula a CPS I"], correctIndex: 1, explanation: "Benzoato + glicina → hipurato (excretado). Fenilbutirato → fenilacetato + glutamina → fenilacetilglutamina. Ambas removem nitrogênio sem o ciclo da ureia.", reference: "Nelson & Cox, Cap. 18" },
      { type: "adjust", question: "Simule deficiência de OTC: ative a deficiência e observe o acúmulo de amônia.", targetParams: { ammonia: { min: 200, max: 800, label: "Amônia" } }, validator: (s) => { const amm = s.ammonia ?? s.amonia ?? 0; return amm >= 200 ? { correct: true, feedback: "Hiperamonemia por deficiência de OTC!" } : { correct: false, feedback: `Amônia: ${amm}. Ative a deficiência de OTC no simulador.` }; }, explanation: "A OTC é a mais comum das deficiências do ciclo da ureia (ligada ao X). Causa hiperamonemia com ácido orótico elevado.", reference: "Lehninger, Cap. 18" },
      { type: "mcq", question: "A citrulinemia tipo I resulta da deficiência de:", options: ["CPS I", "OTC", "ASS (argininosuccinato sintetase)", "Arginase"], correctIndex: 2, explanation: "ASS catalisa: citrulina + aspartato → argininosuccinato. Sua deficiência acumula citrulina↑ no plasma.", reference: "Lehninger, Cap. 18" },
      { type: "mcq", question: "Qual aminoácido fornece o segundo nitrogênio da ureia?", options: ["Glutamina", "Aspartato", "Alanina", "Glicina"], correctIndex: 1, explanation: "Um N da ureia vem de NH₃ livre (via CPS I); o outro vem do aspartato (via ASS). O aspartato é regenerado pelo ciclo de Krebs (oxaloacetato → transaminação).", reference: "Lehninger, Cap. 18" },
      { type: "mcq", question: "O N-acetilglutamato é um ativador alostérico obrigatório de:", options: ["OTC", "CPS I", "ASS", "Arginase"], correctIndex: 1, explanation: "CPS I é inativa sem N-acetilglutamato. Este é sintetizado pela N-acetilglutamato sintase (NAGS), ativada por arginina. Deficiência de NAGS mimetiza deficiência de CPS I.", reference: "Lehninger, Cap. 18" },
      { type: "mcq", question: "A amônia é tóxica para o SNC principalmente porque:", options: ["Causa acidose direta", "Depleta α-cetoglutarato do ciclo de Krebs (fixação em glutamato/glutamina)", "Inibe a glicólise", "Desnatura proteínas"], correctIndex: 1, explanation: "NH₃ + α-cetoglutarato → glutamato (glutamato desidrogenase). Isto depleta o ciclo de Krebs no cérebro, reduzindo a produção de ATP. Glutamina↑ causa edema astrocitário.", reference: "Lehninger, Cap. 18" },
      { type: "mcq", question: "Qual a herança da deficiência de OTC?", options: ["Autossômica recessiva", "Ligada ao X", "Autossômica dominante", "Mitocondrial"], correctIndex: 1, explanation: "OTC é o único defeito do ciclo da ureia ligado ao X. Os demais são autossômicos recessivos. Meninos afetados mais gravemente; portadoras podem ser sintomáticas.", reference: "Lehninger, Cap. 18" },
      { type: "mcq", question: "O lactulose trata a encefalopatia hepática porque:", options: ["Ativa o ciclo da ureia", "Acidifica o cólon, convertendo NH₃ em NH₄⁺ (não absorvível) e acelera o trânsito", "Estimula a urease bacteriana", "Bloqueia a absorção de aminoácidos"], correctIndex: 1, explanation: "Lactulose é metabolizada por bactérias colônicas em ácidos orgânicos → pH↓ → NH₃ → NH₄⁺ (impermeável). Efeito osmótico acelera a eliminação.", reference: "Harrison's, Cap. 335" },
    ],
  };
}

export function getCascataAcidoAraquidonicoChallenges(): ChallengeSet {
  return {
    title: "Desafio: Cascata do Ácido Araquidónico",
    description: "Eicosanóides, COX, LOX, AINEs, corticosteróides e aplicações clínicas.",
    challenges: [
      { type: "mcq", question: "O ácido araquidónico é libertado da membrana pela:", options: ["COX-1", "5-LOX", "Fosfolipase A2 (PLA2)", "Fosfolipase C"], correctIndex: 2, explanation: "A PLA2 cliva os fosfolipídios da membrana na posição sn-2, libertando o ácido araquidónico (20:4). Inibida por lipocortina induzida por corticosteróides.", reference: "Rang & Dale, Cap. 17" },
      { type: "mcq", question: "A aspirina em dose baixa é antiagregante porque:", options: ["Bloqueia COX-2 seletivamente", "Acetila irreversivelmente a COX-1 plaquetária → ↓TXA2", "Inibe a 5-LOX", "Estimula a prostaciclina"], correctIndex: 1, explanation: "A aspirina acetila Ser530 da COX-1. Plaquetas não têm núcleo → não sintetizam nova COX-1. Efeito dura toda a vida plaquetária (~10 dias).", reference: "Rang & Dale, Cap. 17" },
      { type: "mcq", question: "Os coxibes (celecoxib) seletivos para COX-2 reduzem o risco GI mas:", options: ["Não têm efeitos adversos", "Aumentam o risco cardiovascular (↓prostaciclina endotelial)", "São mais eficazes na dor", "Causam mais nefrotoxicidade que AINEs"], correctIndex: 1, explanation: "COX-2 seletivos: ↓PGI2 (prostaciclina vasodilatadora/antiagregante) sem afetar TXA2 (COX-1 plaquetária) → desequilíbrio pró-trombótico.", reference: "Rang & Dale, Cap. 26" },
      { type: "adjust", question: "Use ibuprofeno para reduzir PGE2: ative o ibuprofeno no simulador.", targetParams: { pge2: { min: 0, max: 30, label: "PGE2" } }, validator: (s) => { const pge2 = s.pge2 ?? s.PGE2 ?? 50; return pge2 <= 30 ? { correct: true, feedback: "PGE2 reduzida pelo ibuprofeno!" } : { correct: false, feedback: `PGE2: ${pge2}. Ative o ibuprofeno.` }; }, explanation: "O ibuprofeno inibe COX-1 e COX-2 reversivelmente, reduzindo PGE2 (dor/inflamação) e TXA2 (agregação). Risco GI por ↓PGE2 citoprotetora.", reference: "Rang & Dale, Cap. 26" },
      { type: "mcq", question: "Os leucotrienos (LTB4, LTC4, LTD4) são produzidos pela via da:", options: ["COX-1", "COX-2", "5-lipoxigenase (5-LOX)", "Fosfolipase C"], correctIndex: 2, explanation: "5-LOX converte ácido araquidónico → 5-HPETE → LTA4 → LTB4 (quimiotáxico) ou LTC4/D4/E4 (broncoconstritores). Via importante na asma.", reference: "Rang & Dale, Cap. 17" },
      { type: "mcq", question: "O montelukaste atua como:", options: ["Inibidor de COX", "Antagonista do receptor CysLT1 (leucotrienos cisteínicos)", "Inibidor de 5-LOX", "Agonista de PGI2"], correctIndex: 1, explanation: "Montelukaste bloqueia os receptores CysLT1, antagonizando os efeitos broncoconstritores e inflamatórios de LTC4/D4/E4. Usado na asma.", reference: "Rang & Dale, Cap. 27" },
      { type: "mcq", question: "Os corticosteróides são anti-inflamatórios mais potentes que AINEs porque:", options: ["São mais concentrados", "Inibem tanto COX quanto LOX (via inibição de PLA2)", "Bloqueiam mais receptores", "Têm menor meia-vida"], correctIndex: 1, explanation: "Corticosteróides induzem lipocortina → ↓PLA2 → ↓libertação de ácido araquidónico → ↓TODAS as vias (COX + LOX). AINEs bloqueiam apenas COX.", reference: "Rang & Dale, Cap. 26" },
      { type: "mcq", question: "O tromboxano A2 (TXA2) nas plaquetas causa:", options: ["Vasodilatação", "Agregação plaquetária e vasoconstrição", "Broncodilatação", "Anti-inflamação"], correctIndex: 1, explanation: "TXA2 (via COX-1 plaquetária) é pró-trombótico: ativa receptores TP → agregação + vasoconstrição. Contrabalançado pela PGI2 endotelial.", reference: "Rang & Dale, Cap. 17" },
      { type: "mcq", question: "A asma induzida por aspirina ocorre porque:", options: ["Alergia à aspirina", "Bloqueio de COX desvia ácido araquidónico para a via LOX → ↑leucotrienos", "Aspirina ativa mastócitos", "Aspirina causa broncodilatação"], correctIndex: 1, explanation: "Em indivíduos suscetíveis, o bloqueio de COX pela aspirina redireciona o ácido araquidónico para 5-LOX → ↑LTC4/D4 → broncoespasmo.", reference: "Rang & Dale, Cap. 27" },
      { type: "mcq", question: "A PGI2 (prostaciclina) endotelial é:", options: ["Pró-trombótica", "Antiagregante e vasodilatadora", "Broncoconstritora", "Quimiotáxica"], correctIndex: 1, explanation: "PGI2 (via COX-2 endotelial) antagoniza TXA2: vasodilatação + inibição da agregação plaquetária. Equilíbrio TXA2/PGI2 é fundamental.", reference: "Rang & Dale, Cap. 17" },
    ],
  };
}

export function getLipoproteinasChallenges(): ChallengeSet {
  return {
    title: "Desafio: Metabolismo das Lipoproteínas",
    description: "Vias exógena e endógena, receptores, enzimas e tratamento das dislipidemias.",
    challenges: [
      { type: "mcq", question: "Qual lipoproteína transporta triglicerídeos da dieta?", options: ["VLDL", "LDL", "Quilomícron", "HDL"], correctIndex: 2, explanation: "Quilomícrons são sintetizados no intestino e transportam TG dietéticos. São hidrolisados pela LPL nos capilares → remanescentes captados pelo fígado.", reference: "Lehninger, Cap. 21" },
      { type: "mcq", question: "A LPL (lipoproteína lipase) é ativada por:", options: ["ApoB-100", "ApoC-II", "ApoE", "ApoA-I"], correctIndex: 1, explanation: "ApoC-II é o cofator obrigatório da LPL. Deficiência de ApoC-II causa hipertrigliceridemia grave (pancreatite).", reference: "Lehninger, Cap. 21" },
      { type: "adjust", question: "Simule hipercolesterolemia familiar: reduza receptores de LDL para <30%.", targetParams: { ldlReceptor: { min: 0, max: 30, label: "Receptores de LDL" } }, validator: (s) => { const r = s.ldlReceptor ?? s.LDLReceptor ?? 80; return r <= 30 ? { correct: true, feedback: "HF simulada — LDL muito elevado!" } : { correct: false, feedback: `Receptores: ${r}%. Reduza para ≤30%.` }; }, explanation: "Na HF heterozigótica (~50% receptores) → LDL ~250-450. Homozigótica (<5%) → LDL >500. Risco cardiovascular extremo.", reference: "Harrison's, Cap. 400" },
      { type: "mcq", question: "As estatinas reduzem o LDL-c inibindo:", options: ["CETP", "HMG-CoA redutase", "PCSK9", "LPL"], correctIndex: 1, explanation: "Estatinas inibem a HMG-CoA redutase → ↓síntese de colesterol hepático → ativação de SREBPs → ↑expressão de receptores de LDL → ↑captação de LDL plasmático.", reference: "Rang & Dale, Cap. 23" },
      { type: "mcq", question: "Os inibidores de PCSK9 (evolocumab) reduzem LDL porque:", options: ["Aumentam a síntese de colesterol", "Impedem a degradação dos receptores de LDL", "Bloqueiam a absorção intestinal", "Ativam a LPL"], correctIndex: 1, explanation: "PCSK9 liga-se ao receptor de LDL e direciona-o para degradação lisossômica. Anti-PCSK9 mantém mais receptores na superfície → ↑captação de LDL.", reference: "Harrison's, Cap. 400" },
      { type: "mcq", question: "O HDL-c é 'bom colesterol' porque:", options: ["Transporta TG", "Faz transporte reverso de colesterol (periferia → fígado)", "Aumenta o LDL", "É sintetizado pelas LDL"], correctIndex: 1, explanation: "HDL promove o transporte reverso: captação de colesterol de macrófagos arteriais (via ABCA1) → esterificação por LCAT → entrega ao fígado (via SR-BI).", reference: "Lehninger, Cap. 21" },
      { type: "mcq", question: "Os fibratos reduzem triglicerídeos ativando:", options: ["HMG-CoA redutase", "PPARα", "PCSK9", "Ezetimiba"], correctIndex: 1, explanation: "Fibratos (fenofibrato, bezafibrato) ativam PPARα → ↑LPL, ↑β-oxidação hepática, ↓ApoC-III → TG↓ 30-50%, HDL↑ 10-20%.", reference: "Rang & Dale, Cap. 23" },
      { type: "mcq", question: "A ezetimiba atua:", options: ["No fígado, inibindo a síntese", "No intestino, bloqueando NPC1L1 (absorção de colesterol)", "Nos vasos, removendo placas", "No pâncreas, reduzindo lipase"], correctIndex: 1, explanation: "Ezetimiba bloqueia o transportador NPC1L1 nos enterócitos, reduzindo a absorção intestinal de colesterol em ~50%. LDL↓ 15-20% em monoterapia.", reference: "Rang & Dale, Cap. 23" },
      { type: "mcq", question: "A VLDL é produzida no fígado e contém principalmente:", options: ["Colesterol éster", "Triglicerídeos", "Fosfolipídios", "Ácidos gordos livres"], correctIndex: 1, explanation: "VLDL hepática transporta TG endógenos. É hidrolisada por LPL → IDL → LDL (rica em colesterol). Produção aumentada em obesidade e DM2.", reference: "Lehninger, Cap. 21" },
      { type: "mcq", question: "LDL oxidada na parede arterial é fagocitada por macrófagos, formando:", options: ["Trombo", "Células espumosas (início da aterosclerose)", "Aneurisma", "Placa calcificada"], correctIndex: 1, explanation: "LDL oxidada é reconhecida por receptores scavenger (CD36, SR-A) nos macrófagos. A fagocitação sem regulação forma células espumosas → estria gordurosa → placa aterosclerótica.", reference: "Harrison's, Cap. 291" },
    ],
  };
}

export function getPentosesFosfatoChallenges(): ChallengeSet {
  return {
    title: "Desafio: Via das Pentoses Fosfato e G6PD",
    description: "NADPH, glutationa, estresse oxidativo, deficiência de G6PD e hemólise.",
    challenges: [
      { type: "mcq", question: "A via das pentoses fosfato produz:", options: ["ATP e FADH₂", "NADPH e ribose-5-fosfato", "Lactato e NAD⁺", "Acetil-CoA"], correctIndex: 1, explanation: "A fase oxidativa produz 2 NADPH por glicose-6-P. A fase não-oxidativa produz ribose-5-P (precursor de nucleotídeos).", reference: "Lehninger, Cap. 14" },
      { type: "mcq", question: "O NADPH é essencial nos eritrócitos para:", options: ["Produzir ATP", "Manter a glutationa no estado reduzido (GSH)", "Sintetizar hemoglobina", "Ativar a catalase"], correctIndex: 1, explanation: "NADPH → glutationa redutase → GSH. A GSH detoxifica H₂O₂ e peróxidos via glutationa peroxidase, protegendo a Hb e a membrana.", reference: "Lehninger, Cap. 14" },
      { type: "mcq", question: "A deficiência de G6PD é a enzimopatia mais comum do mundo, afetando:", options: ["100.000 pessoas", "~400 milhões de pessoas", "~1 milhão", "10.000"], correctIndex: 1, explanation: "~400 milhões de pessoas são afetadas globalmente. Alta prevalência em zonas de malária endêmica (vantagem heterozigota contra P. falciparum).", reference: "Harrison's, Cap. 94" },
      { type: "adjust", question: "Simule crise hemolítica: ative a deficiência de G6PD e aplique estresse oxidativo alto.", targetParams: { hemolysis: { min: 50, max: 100, label: "Hemólise" } }, validator: (s) => { const h = s.hemolysis ?? s.hemolise ?? 0; return h >= 50 ? { correct: true, feedback: "Crise hemolítica aguda!" } : { correct: false, feedback: `Hemólise: ${h}%. Ative deficiência de G6PD e aumente o oxidante.` }; }, explanation: "Sem G6PD → ↓NADPH → ↓GSH → Hb oxidada → corpos de Heinz → fagocitose esplênica → anemia hemolítica aguda.", reference: "Harrison's, Cap. 94" },
      { type: "mcq", question: "Corpos de Heinz são:", options: ["Inclusões de ferro", "Precipitados de Hb oxidada desnaturada", "Fragmentos de DNA", "Restos de mitocôndrias"], correctIndex: 1, explanation: "Hb oxidada (meta-Hb) perde o grupo heme e precipita como corpos de Heinz. Detectados com cristal violeta. Causan 'bite cells' no esfregaço.", reference: "Harrison's, Cap. 94" },
      { type: "mcq", question: "Quais substâncias podem precipitar hemólise em deficientes de G6PD?", options: ["Paracetamol e amoxicilina", "Primaquina, sulfonamidas, favas, naftalina", "Insulina e metformina", "Omeprazol e ranitidina"], correctIndex: 1, explanation: "Oxidantes clássicos: primaquina, dapsona, sulfonamidas, nitrofurantoína, favas (vicina/convicina), naftalina. A lista varia por variante genética.", reference: "Harrison's, Cap. 94" },
      { type: "mcq", question: "A via das pentoses fosfato é particularmente ativa em:", options: ["Músculo esquelético", "Fígado, tecido adiposo, eritrócitos e córtex adrenal", "Osso", "Cartilagem"], correctIndex: 1, explanation: "Tecidos que necessitam de NADPH para síntese lipídica (fígado, adiposo), esteroidogênese (adrenal) e defesa oxidativa (eritrócitos).", reference: "Lehninger, Cap. 14" },
      { type: "mcq", question: "O teste de G6PD pode dar falso negativo durante uma crise hemolítica porque:", options: ["A enzima é induzida", "Os eritrócitos mais deficientes já foram destruídos, restando os mais jovens (com mais G6PD)", "O teste não funciona com anemia", "A Hb interfere"], correctIndex: 1, explanation: "Durante a crise, os eritrócitos mais velhos (com menos G6PD residual) são destruídos primeiro. Os reticulócitos jovens têm mais G6PD → resultado falsamente normal.", reference: "Harrison's, Cap. 94" },
      { type: "mcq", question: "A fase não-oxidativa da via das pentoses fosfato utiliza que enzimas?", options: ["G6PD e 6PGD", "Transcetolase e transaldolase", "Piruvato desidrogenase", "Hexoquinase e PFK-1"], correctIndex: 1, explanation: "Transcetolase (requer tiamina/B1) e transaldolase interconvertem açúcares de 3-7 carbonos, ligando a via das pentoses à glicólise.", reference: "Lehninger, Cap. 14" },
      { type: "mcq", question: "A variante G6PD Mediterrânea (classe II) comparada com a A- (classe III):", options: ["É mais leve", "É mais grave — atividade residual <10%", "Tem mesma gravidade", "Não causa hemólise"], correctIndex: 1, explanation: "Classe II (Mediterrânea): <10% atividade → hemólise severa e crônica. Classe III (A-): 10-60% → hemólise autolimitada (eritrócitos jovens protegidos).", reference: "Harrison's, Cap. 94" },
    ],
  };
}

export function getTitulacaoAminoacidosChallenges(): ChallengeSet {
  return {
    title: "Desafio: Titulação de Aminoácidos",
    description: "Curvas de titulação, pKa, pI, estado de carga e aplicações em eletroforese.",
    challenges: [
      { type: "mcq", question: "O ponto isoelétrico (pI) de um aminoácido é:", options: ["O pH onde a enzima funciona melhor", "O pH onde a carga líquida é zero", "O pH de desnaturação", "O pKa do grupo α-COOH"], correctIndex: 1, explanation: "No pI, o aminoácido está como zwitterião com carga líquida zero. Não migra em eletroforese. Solubilidade mínima no pI.", reference: "Lehninger, Cap. 3" },
      { type: "mcq", question: "Para a glicina (pKa1=2.34, pKa2=9.60), o pI é:", options: ["2.34", "5.97", "9.60", "7.00"], correctIndex: 1, explanation: "pI = (pKa1 + pKa2)/2 = (2.34 + 9.60)/2 = 5.97. Para aminoácidos sem cadeia lateral ionizável, é a média dos dois pKa.", reference: "Lehninger, Cap. 3" },
      { type: "mcq", question: "Para o ácido glutâmico (pKa1=2.19, pKaR=4.25, pKa2=9.67), o pI é:", options: ["5.93", "6.96", "3.22", "4.25"], correctIndex: 2, explanation: "Para aminoácidos ácidos: pI = (pKa1 + pKaR)/2 = (2.19 + 4.25)/2 = 3.22. Usa-se os dois pKa mais ácidos.", reference: "Lehninger, Cap. 3" },
      { type: "mcq", question: "A pH 7.4, o glutamato está:", options: ["Carga +1", "Carga 0", "Carga -1", "Carga -2"], correctIndex: 2, explanation: "A pH 7.4: α-COOH desprotonado (-1), γ-COOH desprotonado (-1), α-NH₃⁺ protonado (+1). Carga total: -1. Migra para o ânodo.", reference: "Lehninger, Cap. 3" },
      { type: "mcq", question: "Na curva de titulação, as regiões de tamponamento (plateau) ocorrem:", options: ["Longe dos pKa", "Próximas dos valores de pKa (±1 unidade de pH)", "Apenas no pI", "No pH 7.0"], correctIndex: 1, explanation: "O poder tamponante é máximo quando pH = pKa (50% protonado/desprotonado). Eficaz no intervalo pKa ± 1.", reference: "Lehninger, Cap. 2" },
      { type: "mcq", question: "Para a lisina (pKa1=2.18, pKa2=8.95, pKaR=10.53), o pI é:", options: ["5.57", "9.74", "6.36", "10.53"], correctIndex: 1, explanation: "Para aminoácidos básicos: pI = (pKa2 + pKaR)/2 = (8.95 + 10.53)/2 = 9.74. Usa-se os dois pKa mais básicos.", reference: "Lehninger, Cap. 3" },
      { type: "mcq", question: "A histidina é um aminoácido especial porque:", options: ["É o maior", "Seu pKaR (~6.0) está próximo do pH fisiológico, funcionando como tampão", "É hidrofóbico", "Não é ionizável"], correctIndex: 1, explanation: "O anel imidazol da histidina (pKa ~6.0) permite funcionar como tampão no pH fisiológico e como participante em catálise ácido-base em muitas enzimas.", reference: "Lehninger, Cap. 3" },
      { type: "mcq", question: "Em eletroforese a pH 6.0, a lisina (pI=9.74) migra para:", options: ["Cátodo (polo negativo)", "Ânodo (polo positivo)", "Não migra", "Depende da concentração"], correctIndex: 0, explanation: "A pH 6.0 < pI 9.74 → lisina está protonada (carga +). Migra para o cátodo (polo -). Regra: pH < pI → carga + → migra para −.", reference: "Lehninger, Cap. 3" },
      { type: "mcq", question: "A equação de Henderson-Hasselbalch é:", options: ["pH = pKa + log([HA]/[A⁻])", "pH = pKa + log([A⁻]/[HA])", "pH = -log[H⁺]", "pH = pKa × [A⁻]/[HA]"], correctIndex: 1, explanation: "pH = pKa + log([A⁻]/[HA]). Quando [A⁻] = [HA], log(1) = 0, logo pH = pKa. Fundamental para entender tampões e titulação.", reference: "Lehninger, Cap. 2" },
      { type: "mcq", question: "O aminoácido com maior poder tamponante a pH 7.4 é:", options: ["Glicina (pKa1=2.34)", "Ácido glutâmico (pKaR=4.25)", "Histidina (pKaR=6.00)", "Lisina (pKaR=10.53)"], correctIndex: 2, explanation: "A histidina tem pKaR=6.0, mais próximo do pH 7.4. Tampão eficaz entre pH 5.0-7.0. Nos outros aminoácidos, os pKa estão muito distantes do pH fisiológico.", reference: "Lehninger, Cap. 3" },
    ],
  };
}

export function getOperonLacChallenges(): ChallengeSet {
  return {
    title: "Desafio: Operon Lac",
    description: "Regulação genética bacteriana, repressão catabólica, indução e mutações.",
    challenges: [
      { type: "mcq", question: "O operão lac codifica enzimas para:", options: ["Síntese de lactose", "Metabolismo da lactose (β-galactosidase, permease, transacetilase)", "Síntese de triptofano", "Replicação do DNA"], correctIndex: 1, explanation: "lacZ (β-galactosidase: hidrolisa lactose), lacY (permease: importa lactose), lacA (transacetilase). Organizados em operão policistrónico.", reference: "Lehninger, Cap. 28" },
      { type: "mcq", question: "Para expressão MÁXIMA do operão lac são necessárias:", options: ["Apenas ausência de glicose", "Apenas presença de lactose", "Ausência de glicose E presença de lactose", "Presença de glicose e lactose"], correctIndex: 2, explanation: "Requer: 1) Sem glicose → cAMP↑ → CAP ativo (regulação positiva) + 2) Com lactose → alolactose desreprime LacI (regulação negativa removida).", reference: "Lehninger, Cap. 28" },
      { type: "adjust", question: "Configure indução máxima: glicose 0% e lactose >70%.", targetParams: { glucose: { min: 0, max: 5, label: "Glicose" }, lactose: { min: 70, max: 100, label: "Lactose" } }, validator: (s) => { const g = s.glucose ?? s.glicose ?? 50; const l = s.lactose ?? 50; return (g <= 5 && l >= 70) ? { correct: true, feedback: "Indução máxima do operão lac!" } : { correct: false, feedback: `Glicose: ${g}%, Lactose: ${l}%. Ajuste.` }; }, explanation: "Sem glicose: cAMP↑ → CAP-cAMP liga-se ao promotor. Com lactose: alolactose liga-se ao LacI → repressor dissocia do operador → transcrição máxima.", reference: "Lehninger, Cap. 28" },
      { type: "mcq", question: "O IPTG (isopropil-β-D-tiogalactosídeo) é usado em laboratório porque:", options: ["É uma fonte de energia", "Induz o operão lac mas NÃO é metabolizado (indutor gratuito)", "Bloqueia a RNA polimerase", "Substitui a glicose"], correctIndex: 1, explanation: "IPTG liga-se ao LacI como a alolactose, mas não é clivado pela β-galactosidase. Permite indução estável e controlada em biotecnologia.", reference: "Molecular Biology of the Gene (Watson)" },
      { type: "mcq", question: "A mutação Oc (operador constitutivo) é:", options: ["Trans-dominante", "Cis-dominante", "Recessiva", "Sem efeito"], correctIndex: 1, explanation: "Oc impede a ligação do LacI ao operador. Como o operador só afeta genes no mesmo DNA (cis), a mutação é cis-dominante.", reference: "Lehninger, Cap. 28" },
      { type: "mcq", question: "O crescimento diáuxico demonstra:", options: ["Operão constitutivo", "Repressão catabólica — preferência por glicose sobre lactose", "Mutação no operador", "Falta de lactose"], correctIndex: 1, explanation: "Crescimento diáuxico: bactéria cresce primeiro em glicose (↓cAMP → operão lac OFF). Ao esgotar glicose → ↑cAMP → indução do lac → fase lag → crescimento em lactose.", reference: "Lehninger, Cap. 28" },
      { type: "adjust", question: "Simule repressão catabólica: glicose >70% com lactose presente.", targetParams: { glucose: { min: 70, max: 100, label: "Glicose" }, lactose: { min: 30, max: 80, label: "Lactose" } }, validator: (s) => { const g = s.glucose ?? s.glicose ?? 50; return g >= 70 ? { correct: true, feedback: "Repressão catabólica ativa — operão lac OFF mesmo com lactose!" } : { correct: false, feedback: `Glicose: ${g}%. Aumente para ≥70%.` }; }, explanation: "Com glicose abundante, cAMP↓ → CAP inativo → sem ativação do promotor. O operão permanece OFF apesar da presença de lactose.", reference: "Lehninger, Cap. 28" },
      { type: "mcq", question: "A proteína CAP (catabolite activator protein) liga-se ao:", options: ["Operador", "Promotor (upstream)", "Repressor", "DNA ribossômico"], correctIndex: 1, explanation: "CAP-cAMP liga-se ao sítio CAP upstream do promotor, curvando o DNA e facilitando a ligação da RNA polimerase. É um regulador positivo.", reference: "Lehninger, Cap. 28" },
      { type: "mcq", question: "Uma mutação lacI⁻ (repressor não funcional) causa:", options: ["Operão sempre OFF", "Operão constitutivo (sempre ON)", "Sem efeito", "Dependência de glicose"], correctIndex: 1, explanation: "Sem repressor funcional, não há repressão. O operão é transcrito constitutivamente (nível basal + se CAP ativo). Diferente de Oc: lacI⁻ é trans-recessiva.", reference: "Lehninger, Cap. 28" },
      { type: "mcq", question: "A alolactose é formada pela:", options: ["Permease (LacY)", "β-galactosidase (LacZ) a partir de lactose", "Transacetilase (LacA)", "RNA polimerase"], correctIndex: 1, explanation: "A β-galactosidase, além de hidrolisar lactose em glicose + galactose, catalisa a isomerização em alolactose (1→6 em vez de 1→4), que é o indutor verdadeiro.", reference: "Molecular Biology of the Gene (Watson)" },
    ],
  };
}

